sealed class Cache
{
    private State _state;                       // whole representation: one reference

    public void SwapState(Cache other) =>
        (_state, other._state) = (other._state, _state);      // C# 7 deconstruction

    public void Commit(State fresh) =>          // atomic publish for concurrent readers
        Interlocked.Exchange(ref _state, fresh);
}
